# Sourced, never run, after lib/platform.sh: lets an Edit|Write hook leave without Python on a file
# outside every root. `scope_outside FILE SET...` returns 0 when the scope cache of the project root
# (lib/kit_config.py write_scope_cache, regenerated by the Python the hooks fall back on) is fresh and
# FILE lies under none of the SETs: `uc` (layout.useCase roots), `test` (layout.tests roots), `agg`
# (layout.aggregate globs, on the whole path); `kb` also answers 0 when the knowledge base folder is
# absent. Any doubt answers 1 and the caller asks Python as before: no CLAUDE_PROJECT_DIR, no cache or
# a stale one (a watched config or preset file newer, created or deleted), another kit's cache, a path
# outside the root or not normalised, a `.git` between the file and the root (a linked worktree is
# judged against its own config), a root segment matched. No fork.
# `scope_file_of INPUT` sets SCOPE_FILE to the payload's `file_path`, in kit_path's form, when a regex
# can read it: the key held once, no JSON escape but `\\`. Returns 1 otherwise (jq or Python reads it).
# A fast exit only ever drops a warning the hook would not have given: a wrong pick of the key (top
# level rather than tool_input) is a path the hook's own parse finds empty.
scope_file_of() {
  local rest=${1#*'"file_path"'} re='"file_path"[[:space:]]*:[[:space:]]*"([^"]*)"'
  case "$rest" in *'"file_path"'*) return 1 ;; esac
  [[ $1 =~ $re ]] || return 1
  SCOPE_FILE=${BASH_REMATCH[1]//\\\\//}
  case "$SCOPE_FILE" in *\\*) return 1 ;; esac
  kit_path SCOPE_FILE
}

scope_outside() {
  local file=$1 root=${CLAUDE_PROJECT_DIR:-} tmp kit cache key val rest flag rel d part seg p left want found=""
  local -a uc=() test=() agg=()
  local kb="" kb_seen=""
  shift
  [ -n "$root" ] && [ -n "$file" ] || return 1
  kit_path root
  root=${root%/}
  if [ "${_KIT_PLATFORM:-}" = windows ]; then tmp=/tmp; else tmp=${TMPDIR:-/tmp}; tmp=${tmp%/}; fi
  cache="$tmp/cctoolkit-scope-${root//[^A-Za-z0-9._-]/_}"
  [ -f "$cache" ] || return 1
  kit=${BASH_SOURCE[0]%/lib/scope-cache.sh}
  kit=${kit%/hooks/..}
  case "$kit/" in */./* | */../*) return 1 ;; esac
  kit_path kit
  while IFS=$'\t' read -r key val rest; do
    case "$key" in
      root) [ "$val" = "$root" ] || return 1 ;;
      kit) [ "$val" = "$kit" ] || return 1 ;;
      watch)
        if [ "$rest" = 1 ]; then
          [ -f "$val" ] && ! [ "$val" -nt "$cache" ] || return 1
        else
          [ -e "$val" ] && return 1
        fi ;;
      uc) uc+=("$val") ;;
      test) test+=("$val") ;;
      agg) agg+=("$val") ;;
      kb) kb=$val; kb_seen=1 ;;
    esac
  done <"$cache"
  case "$file" in "$root"/*) ;; *) return 1 ;; esac
  rel=${file#"$root"/}
  case "/$rel/" in *//* | */./* | */../*) return 1 ;; esac
  # A `.git` below the root: a linked worktree (or a nested repository), judged by Python.
  d=${file%/*}
  while [ "$d" != "$root" ]; do
    [ -e "$d/.git" ] && return 1
    d=${d%/*}
    case "$d" in "$root"/* | "$root") ;; *) return 1 ;; esac
  done
  for want in "$@"; do
    case "$want" in
      kb)
        [ -n "$kb_seen" ] || return 1
        [ -d "$kb" ] || return 0 ;;
      agg)
        for p in ${agg[@]+"${agg[@]}"}; do
          # shellcheck disable=SC2053
          [[ $rel == $p ]] && return 1
        done ;;
      uc | test)
        [ "$want" = uc ] && set -- "${uc[@]+"${uc[@]}"}" || set -- "${test[@]+"${test[@]}"}"
        for p in "$@"; do
          # Kit_config.under: every segment of the pattern matches, and the path goes deeper.
          left=$rel found=1
          while :; do
            seg=${p%%/*}
            case "$left" in */*) part=${left%%/*} ;; *) found=""; break ;; esac
            # shellcheck disable=SC2053
            [[ $part == $seg ]] || { found=""; break; }
            left=${left#*/}
            case "$p" in */*) p=${p#*/} ;; *) break ;; esac
          done
          [ -n "$found" ] && return 1
        done ;;
    esac
  done
  return 0
}
